/**
 * hud_pic_assets.h — placeholders de slot do inventario.
 *
 * As 10 imagens de fundo de slot do OTClient (repo opentibiabr/otclient,
 * data/images/inventory/inventory_*.png, 32x32 ARGB), pre-empacotadas
 * como texels GS CT32: A<<24 | B<<16 | G<<8 | R (mesmo packing do
 * spr_loader.c). Alpha 0..255 (GS trata >=0x80 como opaco).
 *
 * PIC_SLOT_TEX[slot] — indice = slot do protocolo (gp_inventory):
 *   0=head 1=neck(amulet) 2=back(backpack) 3=torso(armor)
 *   4=right_hand 5=left_hand 6=legs 7=feet 8=finger(ring)
 *   9=hip(ammo)
 *
 * Regenerar: baixar os 10 PNGs do repo acima e extrair RGBA 32x32
 * (ferramenta em tools/ ou script equivalente).
 */
